<script setup lang="ts">import{ref}from'vue';import{useRouter}from'vue-router';import{useAuthStore}from'../../stores/auth';const username=ref('');const password=ref('');const error=ref('');const busy=ref(false);const auth=useAuthStore();const router=useRouter();async function submit(){error.value='';busy.value=true;try{await auth.login(username.value,password.value);await router.push('/');}catch(e:any){error.value=e?.response?.data?.message??'登录失败，请稍后重试';}finally{busy.value=false;}}</script>
<template><main class="login-page"><section class="brand"><div class="brand-mark">圈</div><h1>主播圈</h1><p>发现真实、有趣的直播生活</p></section><form class="login-card" @submit.prevent="submit"><label>账号<input v-model="username" aria-label="账号" autocomplete="username" placeholder="请输入账号"></label><label>密码<input v-model="password" aria-label="密码" type="password" autocomplete="current-password" placeholder="请输入密码"></label><p v-if="error" class="form-error" role="alert">{{error}}</p><button class="primary-button" type="submit" :disabled="busy">{{busy?'登录中…':'登录'}}</button><p class="demo-tip">测试账号：姜姜668 / abc321</p></form></main></template>
